BEGIN TRANSACTION;
CREATE TABLE chat_messages (
	id INTEGER NOT NULL, 
	session_id INTEGER NOT NULL, 
	role VARCHAR NOT NULL, 
	kind VARCHAR, 
	content TEXT NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(session_id) REFERENCES chat_sessions (id)
);
INSERT INTO "chat_messages" VALUES(3,2,'user','text','What tax rate applies to a newly added product category?','2026-09-17 08:38:14.439727');
INSERT INTO "chat_messages" VALUES(4,2,'bot','matches','[{"score": 1.0, "title": "Understanding tax codes in the invoicing system", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1474564", "text": "Overview Tax codes determine how tax is calculated and reported for each invoice, based on GST (Goods and Services Tax) brackets. Current tax brackets GST 5%: Applies to select essential product categories. GST 12%: Applies to standard mid-tier products. GST 18%: The default rate for most catalog items. GST 28% (New Category): Used for newly onboarded product categories. Invoices using this bracket require Remarks explaining the classification, for audit purposes. If you''re unsure which code to use Check the product''s category listing, or raise a query with the Finance Configuration team."}, {"score": 0.9760624679979518, "title": "Adding a new product to the invoicing catalog", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1343730", "text": "Overview This article describes the general request process for onboarding a new product into the invoicing catalog. Steps Submit a product onboarding request with product name, category, and applicable tax code. The Configuration team reviews and adds the product to the master data table. Allow up to 2 business days for the product to appear across all invoicing screens. Note If a newly added product does not appear where expected after this window, raise a support ticket rather than resubmitting the request."}, {"score": 0.9684979838709676, "title": "How to raise an invoice for a product", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441793", "text": "Overview This article explains the standard steps to raise an invoice for any product already configured in the system. Steps Go to Invoices > Raise Invoice. Select the product, enter quantity, and choose the correct tax code. Add any remarks if applicable, then click Submit. Confirm the invoice appears under ''My Invoices'' with status ''Submitted''."}]','2026-09-17 08:38:14.439727');
INSERT INTO "chat_messages" VALUES(5,2,'user','text','nvoice submission fails even though I selected the new tax bracket and added remarks','2026-09-17 08:38:57.474406');
INSERT INTO "chat_messages" VALUES(6,2,'bot','matches','[{"score": 0.9765625000000001, "title": "Understanding tax codes in the invoicing system", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1474564", "text": "Overview Tax codes determine how tax is calculated and reported for each invoice, based on GST (Goods and Services Tax) brackets. Current tax brackets GST 5%: Applies to select essential product categories. GST 12%: Applies to standard mid-tier products. GST 18%: The default rate for most catalog items. GST 28% (New Category): Used for newly onboarded product categories. Invoices using this bracket require Remarks explaining the classification, for audit purposes. If you''re unsure which code to use Check the product''s category listing, or raise a query with the Finance Configuration team."}, {"score": 0.9692307692307693, "title": "Troubleshooting: invoice stuck in draft status", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1474580", "text": "Problem An invoice remains in Draft status and does not move to Submitted. Steps to resolve Check that all mandatory fields are filled in. Refresh the page and try submitting again. If the issue persists after a refresh, contact support with the invoice ID and a screenshot of any error shown."}, {"score": 0.9684979838709676, "title": "Uploading client tax documents", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/2916354", "text": "Overview Each client may have specific tax documentation on file, such as a tax exemption certificate or GST registration certificate for their jurisdiction. Steps Select the client before uploading their document - documents are tied to the specific client, not the invoice. Upload the relevant certificate in the Tax Document field on the Raise Invoice screen. If you switch to a different client, you must upload that client''s own document - a previous client''s file does not carry over. Note Missing or mismatched tax documentation may delay invoice approval."}]','2026-09-17 08:38:57.474406');
