INSERT INTO "chat_messages" VALUES(10,2,'bot','matches','[{"score": 1.0, "title": "Template - How-to guide", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1343669", "text": "Explain what this how-to article is for. For example, you might write an article to teach people at your company how to set up a corporate email account or file an expense report. Instructions Create a step-by-step guide: Add steps that are simple and self-contained Add illustrations to instructions by typing /image Stick to 3-5 steps per task to avoid overloading readers Highlight important information in a panel like this one. To edit this panel''s color or style, select one of the options in the menu. Related articles The content by label feature automatically displays related articles based on labels you choose. To edit options for this feature, select the placeholder and tap the pencil icon."}, {"score": 0.961166253101737, "title": "How to raise an invoice for a product", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441793", "text": "Overview This article explains the standard steps to raise an invoice for any product already configured in the system. Steps Go to Invoices > Raise Invoice. Select the product, enter quantity, and choose the correct tax code. Add any remarks if applicable, then click Submit. Confirm the invoice appears under ''My Invoices'' with status ''Submitted''."}, {"score": 0.9533577533577533, "title": "SELF-HELP", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1343655", "text": "Description #F4F5F7 In a sentence or two, describe the purpose of this space. Search this Space Filter by Label These are all the labels in use in this space. Select a label to see a list of content the label has been applied to. Recently updated content This list below will automatically update each time somebody in your space creates or updates content. page,whiteboard,database,blog 10 concise true"}]','2026-09-17 08:39:45.050653');
