INSERT INTO "chat_messages" VALUES(12,2,'bot','matches','[{"score": 0.9841269841269842, "title": "How to raise an invoice for a product", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441793", "text": "Overview This article explains the standard steps to raise an invoice for any product already configured in the system. Steps Go to Invoices > Raise Invoice. Select the product, enter quantity, and choose the correct tax code. Add any remarks if applicable, then click Submit. Confirm the invoice appears under ''My Invoices'' with status ''Submitted''."}, {"score": 0.9765625000000001, "title": "Troubleshooting: invoice stuck in draft status", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1474580", "text": "Problem An invoice remains in Draft status and does not move to Submitted. Steps to resolve Check that all mandatory fields are filled in. Refresh the page and try submitting again. If the issue persists after a refresh, contact support with the invoice ID and a screenshot of any error shown."}, {"score": 0.9457932692307692, "title": "Adding a new product to the invoicing catalog", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1343730", "text": "Overview This article describes the general request process for onboarding a new product into the invoicing catalog. Steps Submit a product onboarding request with product name, category, and applicable tax code. The Configuration team reviews and adds the product to the master data table. Allow up to 2 business days for the product to appear across all invoicing screens. Note If a newly added product does not appear where expected after this window, raise a support ticket rather than resubmitting the request."}]','2026-09-17 08:40:10.378465');
