INSERT INTO "chat_messages" VALUES(32,7,'bot','matches','[{"score": 0.499, "title": "How to raise an invoice for a product", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441793", "text": "Overview This article explains the standard steps to raise an invoice for any product already configured in the system. Steps Go to Invoices > Raise Invoice. Select the product, enter quantity, and choose the correct tax code. Add any remarks if applicable, then click Submit. Confirm the invoice appears under ''My Invoices'' with status ''Submitted''."}, {"score": 0.4753, "title": "Invoice approval and submission workflow", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441820", "text": "Overview Once submitted, invoices go through the following stages: Draft, Submitted, Under Review, Approved. Steps Draft invoices can be edited freely. Once submitted, an invoice is locked and routed for review. If rejected, the invoice returns to Draft with reviewer comments."}, {"score": 0.3693, "title": "Uploading client tax documents", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/2916354", "text": "Overview Each client may have specific tax documentation on file, such as a tax exemption certificate or GST registration certificate for their jurisdiction. Steps Select the client before uploading their document - documents are tied to the specific client, not the invoice. Upload the relevant certificate in the Tax Document field on the Raise Invoice screen. If you switch to a different client, you must upload that client''s own document - a previous client''s file does not carry over. Note Missing or mismatched tax documentation may delay invoice approval."}]','2026-09-21 06:56:05.164352');
