INSERT INTO "chat_messages" VALUES(40,10,'bot','matches','[{"score": 0.499, "title": "How to raise an invoice for a product", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441793", "text": "Overview This article explains the standard steps to raise an invoice for any product already configured in the system. Steps Go to Invoices > Raise Invoice. Select the product, enter quantity, and choose the correct tax code. Add any remarks if applicable, then click Submit. Confirm the invoice appears under ''My Invoices'' with status ''Submitted''."}, {"score": 0.4753, "title": "Invoice approval and submission workflow", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441820", "text": "Overview Once submitted, invoices go through the following stages: Draft, Submitted, Under Review, Approved. Steps Draft invoices can be edited freely. Once submitted, an invoice is locked and routed for review. If rejected, the invoice returns to Draft with reviewer comments."}, {"score": 0.3693, "title": "Uploading client tax documents", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/2916354", "text": "Overview Each client may have specific tax documentation on file, such as a tax exemption certificate or GST registration certificate for their jurisdiction. Steps Select the client before uploading their document - documents are tied to the specific client, not the invoice. Upload the relevant certificate in the Tax Document field on the Raise Invoice screen. If you switch to a different client, you must upload that client''s own document - a previous client''s file does not carry over. Note Missing or mismatched tax documentation may delay invoice approval."}]','2026-09-21 09:49:13.934699');
INSERT INTO "chat_messages" VALUES(41,11,'user','text','I need help submitting an invoice with GST 28% (New Category) code','2026-09-21 09:51:02.996020');
INSERT INTO "chat_messages" VALUES(42,11,'bot','matches','[{"score": 0.7024, "title": "Understanding tax codes in the invoicing system", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1474564", "text": "Overview Tax codes determine how tax is calculated and reported for each invoice, based on GST (Goods and Services Tax) brackets. Current tax brackets GST 5%: Applies to select essential product categories. GST 12%: Applies to standard mid-tier products. GST 18%: The default rate for most catalog items. GST 28% (New Category): Used for newly onboarded product categories. Invoices using this bracket require Remarks explaining the classification, for audit purposes. If you''re unsure which code to use Check the product''s category listing, or raise a query with the Finance Configuration team."}, {"score": 0.4436, "title": "Troubleshooting: invoice stuck in draft status", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1474580", "text": "Problem An invoice remains in Draft status and does not move to Submitted. Steps to resolve Check that all mandatory fields are filled in. Refresh the page and try submitting again. If the issue persists after a refresh, contact support with the invoice ID and a screenshot of any error shown."}, {"score": 0.4211, "title": "Uploading client tax documents", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/2916354", "text": "Overview Each client may have specific tax documentation on file, such as a tax exemption certificate or GST registration certificate for their jurisdiction. Steps Select the client before uploading their document - documents are tied to the specific client, not the invoice. Upload the relevant certificate in the Tax Document field on the Raise Invoice screen. If you switch to a different client, you must upload that client''s own document - a previous client''s file does not carry over. Note Missing or mismatched tax documentation may delay invoice approval."}]','2026-09-21 09:51:02.996020');
