INSERT INTO "chat_messages" VALUES(75,22,'bot','matches','[{"score": 0.6494, "title": "Understanding tax codes in the invoicing system", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1474564", "text": "Overview Tax codes determine how tax is calculated and reported for each invoice, based on GST (Goods and Services Tax) brackets. Current tax brackets GST 5%: Applies to select essential product categories. GST 12%: Applies to standard mid-tier products. GST 18%: The default rate for most catalog items. GST 28% (New Category): Used for newly onboarded product categories. Invoices using this bracket require Remarks explaining the classification, for audit purposes. If you''re unsure which code to use Check the product''s category listing, or raise a query with the Finance Configuration team."}, {"score": 0.5056, "title": "Uploading client tax documents", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/2916354", "text": "Overview Each client may have specific tax documentation on file, such as a tax exemption certificate or GST registration certificate for their jurisdiction. Steps Select the client before uploading their document - documents are tied to the specific client, not the invoice. Upload the relevant certificate in the Tax Document field on the Raise Invoice screen. If you switch to a different client, you must upload that client''s own document - a previous client''s file does not carry over. Note Missing or mismatched tax documentation may delay invoice approval."}, {"score": 0.2648, "title": "How to raise an invoice for a product", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441793", "text": "Overview This article explains the standard steps to raise an invoice for any product already configured in the system. Steps Go to Invoices > Raise Invoice. Select the product, enter quantity, and choose the correct tax code. Add any remarks if applicable, then click Submit. Confirm the invoice appears under ''My Invoices'' with status ''Submitted''."}]','2026-09-21 15:03:49.437837');
INSERT INTO "chat_messages" VALUES(76,22,'bot','jira_ticket','{"is_live_jira": true, "ticket_key": "KAN-3", "ticket_url": "https://agnishpaul2002.atlassian.net/browse/KAN-3", "summary": "[Support Escalation] Compliance audit question regarding missing remarks on GST 28% invoice", "user_query": "Compliance audit question regarding missing remarks on GST 28% invoice", "project": "KAN", "status": "OPEN", "priority": "High", "created_at": "2026-09-21 15:03:55 UTC", "reporter": "maya.sharma@meridian.com", "transcript": "* Employee (maya.sharma@meridian.com): Compliance audit question regarding missing remarks on GST 28% invoice\n* Meridian Assistant: [Articles presented: Understanding tax codes in the invoicing system, Uploading client tax documents, How to raise an invoice for a product]", "note": "Live Jira ticket #KAN-3 successfully created in Atlassian project KAN with full conversation transcript."}','2026-09-21 15:03:55.492629');
INSERT INTO "chat_messages" VALUES(77,23,'user','text','Can I raise an invoice for Wireless Mouse?','2026-09-21 19:33:15.981927');
INSERT INTO "chat_messages" VALUES(78,23,'bot','matches','[{"score": 0.499, "title": "How to raise an invoice for a product", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441793", "text": "Overview This article explains the standard steps to raise an invoice for any product already configured in the system. Steps Go to Invoices > Raise Invoice. Select the product, enter quantity, and choose the correct tax code. Add any remarks if applicable, then click Submit. Confirm the invoice appears under ''My Invoices'' with status ''Submitted''."}, {"score": 0.4753, "title": "Invoice approval and submission workflow", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/1441820", "text": "Overview Once submitted, invoices go through the following stages: Draft, Submitted, Under Review, Approved. Steps Draft invoices can be edited freely. Once submitted, an invoice is locked and routed for review. If rejected, the invoice returns to Draft with reviewer comments."}, {"score": 0.3693, "title": "Uploading client tax documents", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/2916354", "text": "Overview Each client may have specific tax documentation on file, such as a tax exemption certificate or GST registration certificate for their jurisdiction. Steps Select the client before uploading their document - documents are tied to the specific client, not the invoice. Upload the relevant certificate in the Tax Document field on the Raise Invoice screen. If you switch to a different client, you must upload that client''s own document - a previous client''s file does not carry over. Note Missing or mismatched tax documentation may delay invoice approval."}]','2026-09-21 19:33:15.981927');
