INSERT INTO "chat_messages" VALUES(252,58,'user','text','Please clear my zoom cache remotely','2026-09-25 06:38:47.700020');
INSERT INTO "chat_messages" VALUES(253,58,'bot','matches','{"ai_answer": "\u26a1 **Remote Action Dispatched via MeshCentral**\n\nThe Zoom cache clear command has been successfully dispatched to your managed device (**AVDGLS5-4**).\n\n**Actions Executed:**\n\u2022 Stopped active Zoom background processes (`Zoom`, `ZoomOpener`, `CptHost`)\n\u2022 Purged corrupted application caches and CEF webcache files in `AppData\\Local\\Zoom` and `AppData\\Roaming\\Zoom`\n\u2022 Cleaned temporary lock files\n\n> \ud83d\udca1 **Next Steps:** Please launch Zoom again and sign in.\n\nPlease test if your meetings and application are working normally. **Did this resolve your issue?**", "matches": [], "remote_action_executed": true}','2026-09-25 06:38:47.700031');
INSERT INTO "chat_messages" VALUES(254,59,'user','text','Hi','2026-09-25 06:47:15.133198');
INSERT INTO "chat_messages" VALUES(255,59,'bot','text','Hello! Welcome to Meridian Enterprise. I''m the Copilot, an AI assistant here to help you with a variety of tasks. 

As your Copilot, I''m knowledgeable about IT standard operating procedures, troubleshooting common issues, invoice compliance, and remote device remediation. Please let me know how I can assist you today - I''m here to provide support and help make your workday more efficient.

How can I be of help?','2026-09-25 06:47:15.133205');
INSERT INTO "chat_messages" VALUES(256,60,'user','text','webcam is not working','2026-09-25 06:50:00.679376');
INSERT INTO "chat_messages" VALUES(257,60,'bot','matches','{"ai_answer": "Okay, let''s troubleshoot the issue with your webcam not working:\n\n1. **Check Windows Privacy Settings for Camera**:\n   - Open the Windows Settings (Win + I)\n   - Navigate to Privacy & Security > Camera\n   - Ensure ''Camera access'' is turned ON\n   - Ensure ''Let apps access your camera'' is turned ON\n   - Scroll down and ensure the specific app (e.g., Zoom, Teams) has camera access enabled\n   - If using a desktop app, ensure ''Let desktop apps access your camera'' is turned ON\n\n2. **Check Sound Settings and Default Device**:\n   - Right-click the speaker icon in the taskbar and select ''Sound settings''\n   - Under ''Input'', check that the correct camera/webcam is selected as the default device\n   - Click on the camera and ensure the volume is not at 0\n   - Test the camera by checking if the input level indicator moves when you speak\n\n3. **Run Windows Audio Troubleshooter**:\n   - Open the Windows Settings (Win + I)\n   - Go to System > Troubleshoot > Other troubleshooters\n   - Find ''Recording Audio'' and click ''Run''\n   - Follow the on-screen instructions\n   - Restart the affected app after the troubleshooter completes\n\nDid these steps resolve the issue with your webcam? Please let me know if you''re still experiencing problems.", "matches": [{"title": "Windows 11 Microphone & Camera Privacy Permissions Troubleshooting", "url": "https://agnishpaul2002.atlassian.net/wiki/spaces/SELFHELP/pages/5341185", "text": "Windows 11 Microphone & Camera Privacy Permissions Troubleshooting - Audio & Video / Privacy Settings. Symptoms: Microphone not working in video conferencing apps (Teams, Zoom, Meet), Camera shows black/blocked in video calls, Windows says microphone access is blocked or denied, App says ''We can''t access your microphone'', Camera privacy indicator shows access is off, Audio routing not working \u2014 can hear but can''t be heard, Microphone works in some apps bu