INSERT INTO "chat_messages" VALUES(328,78,'bot','text','I apologize for the confusion earlier. Based on the context you provided from the Verified Confluence Documentation, it seems you are inquiring about how to raise an invoice for a product or add a new product to the invoicing catalog.

