INSERT INTO "chat_messages" VALUES(515,112,'bot','text','Thanks for providing those details. Based on your response that Zoom is freezing or becoming unresponsive on your laptop since this morning, it seems like the Zoom application cache may be corrupted. Let me recommend the appropriate troubleshooting step:

